mapper.update:
UPDATE lambda_assignments
SET end_date = #{endDate}
WHERE lambda_assignment_id = #{lambdaAssignmentId} AND deleted_at IS NULL

UPDATE lambda_assignments
SET end_date = #{deletedAt}, deleted_at = #{deletedAt}
WHERE lambda_assignment_id = #{lambdaAssignmentId} AND deleted_at IS NULL

mapper.select:
SELECT lambda_assignment_id, lambda_id, assignment_date, is_testing, end_date, deleted_at, location_id
FROM lambda_assignments
WHERE lambda_id = #{lambdaId}
  AND deleted_at IS NULL
  AND location_id = #{locationId}
